(55, '038/PWI-BA/I/2026', '2026-01-30', 'SURAT TUGAS', 'published', NULL, 'Serang -  Provinsi Banten', 'Kegiatan Hari Pers Nasional', 'Kegiatan Hari Pers Nasional', NULL, NULL, NULL, NULL, 'Serang - Provinsi Banten', '2026-02-06', '2026-02-10', NULL, NULL, NULL, 'Wardoyo, S.I.Kom', 'Deni Arianto', '2026-09-03 07:23:00', '2026-09-03 07:23:00', '29087829-c858-40cf-83c8-c6c16e008597', 'TERVERIFIKASI & SAH', 'bbb1929b90835425a673a9f451e107f60b99245883234435af37db09d8e65f40');
