INSERT INTO `meeting_minutes` (`id`, `judul_rapat`, `tanggal`, `waktu_mulai`, `waktu_selesai`, `tempat`, `pemimpin_rapat`, `notulis`, `agenda`, `pembahasan`, `kesimpulan`, `file_lampiran`, `created_at`, `updated_at`) VALUES
(1, 'Rapat Pleno Persiapan Turnamen Mini Soccer Piala PWI 2026 & Konsolidasi UKW', '2026-08-10', '09:00:00', '12:30:00', 'Sekretariat PWI Kabupaten Banyuasin, Jl. Merdeka No. 3', 'Wardoyo, S.I.Kom (Ketua PWI)', 'Deni Arianto (Sekretaris PWI)', '1. Pembentukan Panitia Pelaksana Turnamen Mini Soccer 2026\n2. Sosialisasi Program Uji Kompetensi Wartawan (UKW) Angkatan VII\n3. Penertiban Administrasi KTA dan Iuran Anggota', 'Rapat dibuka pukul 09.00 WIB oleh Ketua PWI Banyuasin. Dilanjutkan pemaparan ketua SIWO mengenai kesiapan lapangan Sedulang Setudung dan koordinasi izin keramaian ke Polres Banyuasin. Bendahara memaparkan estimasi anggaran dan penggalangan sponsor. Dilanjutkan pembahasan pendaftaran peserta UKW bagi 16 wartawan yang belum memiliki sertifikat UKW.', '1. Turnamen Mini Soccer dijadwalkan tanggal 19-31 Agustus 2026 dengan 16 tim peserta mitra instansi.\n2. Mengirimkan surat pemberitahuan UKW ke PWI Sumsel.\n3. Seluruh anggota PWI Banyuasin wajib berpartisipasi aktif dalam kepanitiaan.', NULL, '2026-09-03 06:23:40', '2026-09-03 06:23:40'),
(2, 'Rapat Evaluasi Kinerja Semester I & Verifikasi Berkas Keanggotaan', '2026-06-15', '13:30:00', '16:00:00', 'Ruang Rapat Sekretariat PWI Banyuasin', 'Wardoyo, S.I.Kom', 'Deni Arianto', '1. Evaluasi Liputan Berita dan Website Resmi PWI\n2. Verifikasi Data Wartawan Aktif dan Non-Aktif\n3. Rencana Bantuan Hukum & Pembelaan Wartawan', 'Pembahasan mengenai pentingnya pembaruan website profil dan sistem informasi keanggotaan PWI Banyuasin agar mudah diakses publik dan dinas. Bidang Pembelaan Wartawan melaporkan situasi kondusif di lapangan.', '1. Merilis portal digital baru terintegrasi.\n2. Mewajibkan seluruh anggota memperbarui masa berlaku KTA PWI.\n3. Menjadwalkan safari jurnalistik ke instansi Forkopimda.', NULL, '2026-09-03 06:23:41', '2026-09-03 06:23:41');
