INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES
(1, 'nama_pwi', 'PWI Kabupaten Banyuasin', '2026-09-03 06:23:39', '2026-09-03 06:23:39'),
(2, 'alamat_kantor', 'Jalan Merdeka NO 3 RT 02 RW 02 Kelurahan Mulya Agung, Kecamatan Banyuasin III, Kabupaten Banyuasin - Sumatera Selatan (30914)', '2026-09-03 06:23:39', '2026-09-04 12:33:31'),
(3, 'kota', 'Pangkalan Balai', '2026-09-03 06:23:39', '2026-09-03 06:23:39'),
(4, 'no_telp', '0853-7799-1976', '2026-09-03 06:23:39', '2026-09-03 06:23:39'),
(5, 'email', 'sekretariat@pwiba.or.id', '2026-09-03 06:23:39', '2026-09-03 17:04:18'),
(6, 'ketua_nama', 'Wardoyo, S.I.Kom', '2026-09-03 06:23:39', '2026-09-03 06:23:39'),
(7, 'ketua_sambutan', 'Melalui platform digital terintegrasi ini, kami berkomitmen memperkuat peran PWI Banyuasin dalam peningkatan profesionalisme wartawan melalui pelatihan, Uji Kompetensi dan kolaborasi dengan berbagai pihak guna mendukung kemajuan pers yang merdeka dan bermartabat di Bumi Sedulang Setudung.', '2026-09-03 06:23:39', '2026-09-03 06:23:39'),
(8, 'visi', 'Memperkuat peran PWI Banyuasin dalam peningkatan integritas  dan profesionalitas  wartawan melalui pelatihan, Uji Kompetensi dan kolaborasi dengan berbagai pihak.', '2026-09-03 06:23:39', '2026-09-08 15:24:38'),
(9, 'misi', '1. Menjadikan PWI Banyuasin sebagai wadah yang lebih solid dan berdaya saing.\r\n2. Berkontribusi nyata bagi masyarakat serta kemajuan pers nasional.\r\n3. Kontribusi pers kepada masyarakat itu harus tegas. Saran saya, misal,  Pers berkontribusi mencerdaskan masyarakat melalui karya jurnalistik dan kebebasan pers.\r\n4. Kemitraan strategis itu adalah instansi pemerintah, perusahaan swasta dan negara, serta organisasi yang saling memperkuat penyebaran informasi', '2026-09-03 06:23:39', '2026-09-08 07:24:08'),
(10, 'kd_pwi', '14', '2026-09-03 07:23:01', '2026-09-03 07:23:01'),
(11, 'nm_pwi', 'Banyuasin', '2026-09-03 07:23:01', '2026-09-03 07:23:01'),
(12, 'nama_kabupaten', 'Kabupaten Banyuasin', '2026-09-03 07:23:01', '2026-09-03 07:23:01'),
(13, 'nm_kota', 'Pangkalan Balai', '2026-09-03 07:23:01', '2026-09-03 07:23:01'),
(14, 'nama_ketua', 'Wardoyo, S.I.Kom', '2026-09-03 07:23:01', '2026-09-03 07:23:01'),
(15, 'nama_sekretaris', 'Deni Arianto', '2026-09-03 07:23:01', '2026-09-03 07:23:01'),
(16, 'nama_bendahara', 'Ridho Andi Sucipto, M.Pd', '2026-09-03 07:23:01', '2026-09-03 07:23:01'),
